(() => {
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const content={...PART_ONE,...PART_TWO,...PART_THREE,...PART_FOUR,...PART_FIVE,...PART_SIX,...PART_SEVEN,...PART_EIGHT,...PART_NINE};
  const canRun=t=>t.runtime!=='native'||!!t.browser;
  for(const chapter of COURSE.chapters.filter(c=>c.status==='ready')){
    for(const topic of chapter.topics){
      const t=content[chapter.id].topics[topic.id];
      if(!canRun(t))continue;
      LESSONS.push({id:`example-${chapter.id}-${topic.id}`,isExample:true,chapterId:chapter.id,topicId:topic.id,section:chapter.part,
        title:topic.title,time:'Worked example',tag:`Part ${chapter.part+1}`,concept:'Read, run, and change a complete program.',body:t.intro,
        detail:`This is an ungraded worked example. <a href="#/chapter/${chapter.id}/${topic.id}">Return to its explanation and question</a>.`,
        task:t.tryit,hint:'Run the unchanged example first. Change one thing at a time, predict the result, then run again.',
        code:t.code,files:t.files,solution:t.code,input:t.input,tests:[{name:'Original example output',input:t.input,expected:t.expected}],
        assessment:'Checking an example compares it with the original output; it does not add to practice progress.',
        example:{code:t.code,html:'<pre>'+escape(t.expected)+'</pre>',question:t.question,choices:t.choices,answer:t.answer,why:t.why}});
    }
  }
  function workshop(chapter,data){
    const plan=data.practicePlan;if(!plan)return '';
    const final=chapter.topics.find(topic=>plan.example===`${chapter.id}-${topic.id}`)||chapter.topics.at(-1);
    const native=data.topics[final.id].runtime==='native';
    return `<section class="chapter-practice"><h2>Build it yourself</h2><p>${escape(plan.goal)}</p><p>Start from <a href="#/chapter/${chapter.id}/${final.id}">${escape(final.title)}</a>. The tasks below are extensions for you to implement; the page does not add them automatically.</p><ol>${plan.tasks.map(task=>`<li>${escape(task)}</li>`).join('')}</ol><details><summary>Check your work</summary><ul>${plan.checks.map(check=>`<li>${escape(check)}</li>`).join('')}</ul><p>${plan.command?'The audit command checks the documented portable target and fixtures. Additional platform services and stronger guarantees need their own tests.':'RUN_ONLY=1 shows the edited program’s output. Omit it to check the unchanged starter against the original output. Your extension needs its own checks.'}</p></details>${native?courseExecution.panel({...chapter,nativeDemo:null,command:plan.command||`make example EXAMPLE=${plan.example} RUN_ONLY=1`,workspace:plan.workspace||chapter.workspace,execution:{mode:'linux',reason:plan.command?'Run the audited C17 target and its independent fixtures. The automated repository checks provide evidence from other operating systems.':'This command runs the complete final example. Extend it into the chapter project, add independent cases, and retain the earlier contracts.'}}):`<p><a href="#/chapter/${chapter.id}/${final.id}">Run and extend the chapter example →</a></p>`}</section>`;
  }
  function practice(chapter,data,topic){
    if(data.practice){const firstPractice=topic?chapter.labs[0]:data.practice,l=LESSONS.find(l=>l.id===firstPractice);return `<section class="chapter-practice"><h2>Chapter practice</h2>${topic?`<h3>${escape(l.title)}</h3><p>Practise this chapter in a separate editor. Mark this reading complete as you open practice, or leave it unmarked to return later.</p>`:`<p>Open the interactive exercise below. Edit its starter code, choose Run code, then use Check output to test your solution.</p>`}${topic?`<button type="button" class="primary-link" data-complete-and-practice="${firstPractice}" data-reading="${chapter.id}/${topic.id}">Mark lesson complete and start practice →</button><p><a href="#/lesson/${firstPractice}">Start practice without marking this lesson complete →</a></p>`:`<a class="primary-link" href="#/lesson/${data.practice}">Open exercise: ${escape(l.title)} →</a>`}${chapter.labs.filter(id=>id!==firstPractice).map(id=>`<p><a href="#/lesson/${id}">${escape(LESSONS.find(l=>l.id===id).title)} →</a></p>`).join('')}</section>`+workshop(chapter,data);}
    if(data.practicePlan)return workshop(chapter,data);
    const project=data.nativePractice;const implementation=`native/projects/${project.id}/${project.id==='record-store'?'store.c':'record.c'}`;
    return `<section class="chapter-practice"><h2>${escape(project.title)}</h2><p>The course supplies starter files with TODOs, tests, and a separate reference in Browser Linux. Its initial failure is expected; complete the implementation before checking your work.</p>${courseExecution.panel({...chapter,status:'ready',nativeDemo:null,command:`make project PROJECT=${project.id}`,workspace:`native/projects/${project.id}`,execution:{mode:'linux',reason:`In Edit a course file in this browser, select ${implementation} and complete its TODOs. Choose Run edited source in Linux to transfer the current editor text and run the project tests.`}})}</section>`;
  }
  function debuggingLab(chapter,t){
    const lab=t.lab;if(!lab)return '';
    const launch=courseExecution.panel({...chapter,nativeDemo:null,status:'ready',workspace:lab.workspace,command:lab.command,execution:{mode:'linux',reason:'Optional GDB investigation in Browser Linux. The small browser command workspace does not provide GDB; use the full Linux terminal for this lesson.'}});
    return `<section class="debugging-lab" aria-label="Optional debugging lab"><h2>${escape(lab.title)}</h2><p><strong>Optional · Browser Linux.</strong> You can continue the course without running GDB. Starter check failures are deliberate; they become your regression tests.</p><p><a href="${escape(lab.skip.href)}">${escape(lab.skip.label)} →</a></p>${launch}<h3>Investigate one step at a time</h3><ol class="debugging-steps">${lab.steps.map(step=>`<li><h4>${escape(step.title)}</h4><p>${escape(step.body)}</p><pre><code>${escape(step.command)}</code></pre></li>`).join('')}</ol><details><summary>Hint and separate reference</summary><p>${escape(lab.hint)}</p></details></section>`;
  }
  function nativeExample(chapter,topic,t){
    const files=t.files||{'main.c':t.code};
    const listing=Object.entries(files).sort(([a],[b])=>a==='main.c'?-1:b==='main.c'?1:a.localeCompare(b)).map(([name,code])=>name==='main.c'?`<h3>${escape(name)}</h3><pre><code>${escape(code)}</code></pre>`:`<details><summary>${escape(name)}</summary><pre><code>${escape(code)}</code></pre></details>`).join('');
    const id=chapter.id+'-'+topic.id;
    const command=t.command||`make example EXAMPLE=${id}`;
    return `<div class="native-example" data-native-example="${id}">${courseExecution.panel({...chapter,status:'ready',nativeDemo:null,command:`${command} RUN_ONLY=1`,workspace:`native/examples/${id}`,execution:{mode:'linux',kind:'example',reason:'Use Browser Linux. Run this at the imported repository root to build the files and print their output.'}})}<details class="native-source"><summary>Read the original source files</summary>${listing}</details><details><summary>Check the original program</summary><p>At ~/work/c-foundry in the Linux terminal, run <code>${escape(command)}</code> with the starter files. This checks their output against the original example; use RUN_ONLY=1 when exploring changed output.</p></details></div>`;
  }
  function helpLab(chapter,topic){
    if(chapter.id!=='first-program'||topic.id!=='6')return '';
    return window.cManuals?.practice?cManuals.practice():'<p><a href="#/manual/printf.3">Read the bundled printf(3) manual →</a></p>';
  }
  function readingGuide(t){return t.guide?`<section class="reading-guide" aria-label="Documentation lookup guide">${t.guide.map((step,i)=>`<h2>${i+1}. ${escape(step.title)}</h2><p>${escape(step.body)}</p>${step.command?`<pre><code>${escape(step.command)}</code></pre>`:''}`).join('')}</section>`:'';}
  function render(chapter,topic){
    const data=content[chapter.id],part=chapter.part+1;
    const position=topic?chapter.topics.indexOf(topic):-1;
    const subsequent=COURSE.chapters[chapter.number];
    const previous=position>0?chapter.topics[position-1]:null;
    const following=position>=0?chapter.topics[position+1]:chapter.topics[0];
    const header=`<nav class="reading-breadcrumb" aria-label="Breadcrumb"><a href="#/course">Course</a><span aria-hidden="true">/</span><a href="#/chapter/${chapter.id}">Chapter ${chapter.number}</a><span>Part ${part}</span></nav><nav class="chapter-controls" aria-label="Chapter navigation"><label for="chapter-jump">In this chapter<select id="chapter-jump"><option value="/chapter/${chapter.id}" ${!topic?'selected':''}>Chapter overview</option>${chapter.topics.map((item,index)=>`<option value="/chapter/${chapter.id}/${item.id}" ${topic?.id===item.id?'selected':''}>${index+1}. ${escape(item.title)}</option>`).join('')}${chapter.labs.map(id=>`<option value="/lesson/${id}">Practice: ${escape(LESSONS.find(l=>l.id===id).title)}</option>`).join('')}</select></label><div class="reading-shortcuts">${previous?`<a href="#/chapter/${chapter.id}/${previous.id}" aria-label="Previous: ${escape(previous.title)}">← Previous</a>`:''}${following?`<a href="#/chapter/${chapter.id}/${following.id}" aria-label="${topic?'Next':'Start'}: ${escape(following.title)}">${topic?'Next':'Start chapter'} →</a>`:data.practice?`<a href="#/lesson/${data.practice}">Practice →</a>`:topic&&subsequent?`<a href="#/chapter/${subsequent.id}/1" aria-label="Next chapter: ${escape(subsequent.title)}">Next chapter →</a>`:''}</div></nav><p class="eyebrow">${topic?`Lesson ${position+1} of ${chapter.topics.length}`:`Chapter ${chapter.number} · ${chapter.topics.length} lessons`}</p><h1 tabindex="-1">${escape(topic?topic.title:chapter.title)}</h1>`;
    if(!topic)return header+`<p class="lesson-deck">${escape(data.intro)}</p><h2>What you will learn</h2><ul>${data.outcomes.map(s=>'<li>'+escape(s)+'</li>').join('')}</ul>${chapter.id==='big-o'?'<p><a class="primary-link" href="#/big-o">Compare counted search operations →</a></p>':''}<h2>Read in order</h2><ol class="topic-list">${chapter.topics.map(t=>`<li><a href="#/chapter/${chapter.id}/${t.id}">${escape(t.title)}</a></li>`).join('')}</ol>${practice(chapter,data)}<p class="supporting">Teaching baseline: C17. ${chapter.execution.mode==='browser'?'These examples run in the page.':chapter.topics.some(topic=>canRun(data.topics[topic.id]))?'Browser examples run here. Open Browser Linux for the project and tools.':'Run the examples and project in Browser Linux.'} <a href="#/setup">Execution and setup guide</a>.</p><nav class="page-navigation"><a href="#/chapter/${chapter.id}/1">Start the chapter →</a>${chapter.number>1?`<a href="#/chapter/${COURSE.chapters[chapter.number-2].id}">Previous chapter</a>`:''}</nav>`;
    const t=data.topics[topic.id],i=chapter.topics.indexOf(topic),next=chapter.topics[i+1],prev=chapter.topics[i-1],nextChapter=COURSE.chapters[chapter.number];
    const browser=canRun(t),help=chapter.id==='first-program'&&topic.id==='6';
    const fileList=Object.keys(t.files||{'main.c':t.code}).map(name=>`<code>${escape(name)}</code>`).join(', ');
    const startingState=browser
      ? `On your first visit, the editor opens with ${fileList}. ${t.files?'Choose a filename above the editor to switch files. Run code builds all the C files together.':''}`
      : `The repository provides the starter in <code>native/examples/${chapter.id}-${topic.id}/</code>. Open Browser Linux, import the course bundle, and choose Edit a course file in this browser to edit ${fileList} in that folder. Download the edited file, upload it into the terminal, then paste its Copy apply and run command. The source listing on this lesson is read-only.`;
    const input=t.input?`<p>Prepared input for the starter</p><pre class="example-input">${escape(t.input)}</pre>`:'';
    return header+`<article class="topic-content"><p class="lesson-deck">${escape(t.intro)}</p>${t.orientation?`<p class="lesson-orientation">${t.orientation}</p>`:''}<p>${t.explanation}</p>${conceptDiagrams.render(chapter,topic,'explanation')}${help?'':readingGuide(t)}${helpLab(chapter,topic)}${debuggingLab(chapter,t)}<section class="worked-example"><h2>${escape(help?'3. Test your prediction with C':t.exampleTitle||'Run the worked example')}</h2><p>${startingState}</p>${input}<p>${browser?'Choose <strong>Run code</strong> and read the output in <strong>Console</strong>. To run the original example after editing, open <strong>Editor tools</strong> and choose <strong>Restore starter</strong>. You can recover your previous edits with <strong>Undo replacement</strong>.':'Run the command below with the starter files unchanged. Read the result in the Linux terminal. For an edited example, keep RUN_ONLY=1 so changed output is shown instead of checked against the original.'}</p>${help?'<p>Keep the program unchanged for the first run. In Console, compare the <code>count=</code> line with your prediction above. The first output line is the message; <code>count=</code> reports the return value of the first printf call.</p>':'<h3>Try a change</h3><p>'+escape(t.tryit)+'</p>'}${browser?'<div id="inline-editor-host"></div>'+(t.browser?`${t.browser.note?`<p class="supporting">${escape(t.browser.note)}</p>`:''}<details class="native-alternative"><summary>Browser Linux and source files</summary>${nativeExample(chapter,topic,t)}</details>`:''):nativeExample(chapter,topic,t)}${t.artifact?`<p><a href="${escape(t.artifact.href)}" download>${escape(t.artifact.label)} ↓</a></p>`:''}<details class="original-output"><summary>Compare with the original output</summary><pre>${escape(t.expected)}</pre></details><p class="example-walkthrough">${t.walkthrough}</p>${conceptDiagrams.render(chapter,topic,'after-example')}${help&&window.cManuals?.transfer?cManuals.transfer(t.tryit):''}${t.extension?`<details class="topic-extension"><summary>Extend the example</summary><p>${escape(t.extension)}</p></details>`:''}</section><h2>Watch for this</h2><p>${t.pitfall}</p><section class="prediction"><h2>Check your understanding</h2><fieldset><legend>${escape(t.question)}</legend>${t.choices.map((s,j)=>`<label><input type="radio" name="topic-check" value="${j}"> ${escape(s)}</label>`).join('')}</fieldset><button data-topic-check data-chapter="${chapter.id}" data-topic="${topic.id}">Check answer</button><p id="topic-feedback" role="status"></p></section>${lessonReferences.render(chapter,topic,t)}</article><section class="lesson-completion" aria-label="Lesson completion"><label class="completion-control"><input type="checkbox" data-lesson-complete="${chapter.id}/${topic.id}" aria-describedby="completion-save-note"> Mark lesson as done</label><p id="completion-save-note" role="status">Mark this when you finish the lesson.</p></section>${!next?practice(chapter,data,topic):''}<nav class="page-navigation">${prev?`<a href="#/chapter/${chapter.id}/${prev.id}">← Previous topic</a>`:`<a href="#/chapter/${chapter.id}">← Chapter overview</a>`}${next?`<a href="#/chapter/${chapter.id}/${next.id}">Next: ${escape(next.title)} →</a>`:nextChapter?`<a href="#/chapter/${nextChapter.id}${nextChapter.status==='ready'?'/1':''}">Next chapter: ${escape(nextChapter.title)} →</a>`:'<a href="#/course">Course map →</a>'}</nav>`;
  }
  document.addEventListener('click',event=>{const b=event.target.closest('[data-topic-check]');if(!b)return;const t=content[b.dataset.chapter].topics[b.dataset.topic],selected=document.querySelector('input[name="topic-check"]:checked');document.getElementById('topic-feedback').textContent=selected?`${Number(selected.value)===t.answer?'Correct.':'Not quite.'} ${t.why}`:'Choose an answer first.';});
  window.authoredLessons={render,content,canRun};
})();
